int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<int> P(N);
    for (int i = 0; i < N; ++i) cin >> P[i];

    // If K = 1, operation changes nothing.
    if (K == 1) {
        bool ok = true;
        for (int i = 0; i < N; ++i) {
            if (P[i] != i + 1) {
                ok = false;
                break;
            }
        }
        cout << (ok ? "Yes\n" : "No\n");
        return 0;
    }

    // For K >= 2:
    // Each operation is a K-cycle, whose sign is (-1)^(K-1).
    // - If K is odd, every operation is even, so permutation parity is invariant.
    //   Therefore sortable iff P is even.
    // - If K is even, operations include odd permutations; in fact they generate all S_N
    //   (for N >= K >= 2), so every permutation is sortable.

    if (K % 2 == 0) {
        cout << "Yes\n";
        return 0;
    }

    // K odd: check parity of permutation P.
    vector<bool> vis(N, false);
    int cycles = 0;
    for (int i = 0; i < N; ++i) {
        if (!vis[i]) {
            ++cycles;
            int cur = i;
            while (!vis[cur]) {
                vis[cur] = true;
                cur = P[cur] - 1;
            }
        }
    }

    // parity = (N - number_of_cycles) mod 2
    bool evenPermutation = ((N - cycles) % 2 == 0);
    cout << (evenPermutation ? "Yes\n" : "No\n");

    return 0;
}

