    int *P = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &P[i]);

    if (K == 1) {
        int ok = 1;
        for (int i = 1; i <= N; i++) {
            if (P[i] != i) {
                ok = 0;
                break;
            }
        }
        printf(ok ? "Yes\n" : "No\n");
        free(P);
        return 0;
    }

    if (K == N) {
        int ok = 1;
        for (int shift = 0; shift < N; shift++) {
            ok = 1;
            for (int i = 1; i <= N; i++) {
                int idx = i - shift;
                if (idx <= 0) idx += N;
                if (P[idx] != i) {
                    ok = 0;
                    break;
                }
            }
            if (ok) break;
        }
        printf(ok ? "Yes\n" : "No\n");
        free(P);
        return 0;
    }

    /* For 1 < K < N:
       Each operation is a K-cycle, whose sign is (-1)^(K-1).
       - If K is odd, the operation is even, so parity of permutation is invariant.
         Reachable permutations are exactly those with same parity as identity => even permutations.
       - If K is even, the operation is odd. Since windows overlap and 1 < K < N,
         these operations generate the full symmetric group, so every permutation is reachable.
    */

    if (K % 2 == 0) {
        printf("Yes\n");
        free(P);
        return 0;
    }

    /* K odd: need permutation parity to be even */
    int *vis = (int *)calloc(N + 1, sizeof(int));
    int cycles = 0;
    for (int i = 1; i <= N; i++) {
        if (!vis[i]) {
            cycles++;
            int x = i;
            while (!vis[x]) {
                vis[x] = 1;
                x = P[x];
            }
        }
    }
    /* sign = (-1)^(N-cycles), even iff (N-cycles) % 2 == 0 */
    if (((N - cycles) & 1) == 0) printf("Yes\n");
    else printf("No\n");

    free(vis);
    free(P);
    return 0;
}

