public class Main {
    // Fast input
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int T;
        try {
            T = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        while (T-- > 0) {
            int N = fs.nextInt();
            int K = fs.nextInt();
            int[] P = new int[N + 1];
            for (int i = 1; i <= N; i++) P[i] = fs.nextInt();

            boolean ok;

            if (K == 1) {
                // Operation does nothing, so permutation must already be sorted.
                ok = true;
                for (int i = 1; i <= N; i++) {
                    if (P[i] != i) {
                        ok = false;
                        break;
                    }
                }
            } else if (K == N) {
                // Only whole-array rotations are possible.
                // Sorted permutation can be reached iff current permutation is a cyclic rotation of 1..N.
                ok = true;
                int first = P[1];
                for (int i = 1; i <= N; i++) {
                    int expected = ((first - 1 + (i - 1)) % N) + 1;
                    if (P[i] != expected) {
                        ok = false;
                        break;
                    }
                }
            } else {
                // For 1 < K < N, these moves generate all permutations.
                ok = true;
            }

            out.append(ok ? "Yes" : "No").append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys
from math import gcd

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    P = [int(next(it)) for _ in range(N)]

    if K == 1:
        # No operation changes anything
        if all(P[i] <= P[i+1] for i in range(N-1)):
            print("Yes")
        else:
            print("No")
        return

    G = gcd(N, K)
    # Group elements by index modulo G
    groups = [[] for _ in range(G)]
    for i, val in enumerate(P):
        groups[i % G].append(val)

    # Sort each group
    for g in groups:
        g.sort()

    # Reconstruct the array from sorted groups
    sorted_arr = [0] * N
    for i in range(N):
        sorted_arr[i] = groups[i % G][i // G]

    if all(sorted_arr[i] <= sorted_arr[i+1] for i in range(N-1)):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
